Business:"Edit Business & Branding",activeBadge:"Active Store",switchToBusiness:"Switch to this Store",allStores:"All Businesses",businessNameLabel:"Business / Store Name",businessNamePlaceholder:"e.g. Carpinchill Coffee Roasters",categoryLabel:"Business Category",brandColorLabel:"Brand Identity Color",logoLabel:"Business Logo",uploadLogo:"Upload Business Logo",descriptionLabel:"Description / Bio",descriptionPlaceholder:"Tell customers about your store or loyalty program...",websiteLabel:"Website URL",instagramLabel:"Instagram / Social Handle",saveChanges:"Save Business & Branding",createdSuccess:"Business created successfully!",updatedSuccess:"Business settings updated!",noBusinessesTitle:"No Businesses Found",noBusinessesDesc:"Get started by creating your first business.",campaignsCount:"Campaigns",staffCount:"Staff members",brandPreview:"Brand Preview in Customer Wallet",chooseColor:"Pick a Color Theme",menuTabTitle:"Business Menu",menuTypeLabel:"Menu Integration Type",menuTypeNone:"No Menu",menuTypeLink:"External Link (Drive, Web, Canva)",menuTypeFile:"Upload Menu File (PDF or Image)",menuTypeDigital:"Interactive Digital Menu",menuUrlLabel:"Menu Link / URL",menuUrlPlaceholder:"https://drive.google.com/... or https://yourmenu.com",menuUrlHint:"Paste the direct link to your menu on Google Drive, Notion, Canva, or website.",uploadMenuFile:"Upload Menu (PDF / Image)",uploadingMenuFile:"Uploading menu...",menuFileHint:"Supports PDF, JPG, PNG or WEBP up to 10MB.",menuFileUploaded:"Menu file uploaded and linked",digitalMenuTitle:"Digital Menu Builder",digitalMenuSubtitle:"List your products or services with prices and descriptions for your customers.",addMenuItem:"Add Item to Menu",itemNameLabel:"Item Name",itemNamePlaceholder:"e.g. Flat White Specialty Coffee",itemPriceLabel:"Price",itemPricePlaceholder:"e.g. $4.50 or $4.500",itemCategoryLabel:"Category",itemCategoryPlaceholder:"e.g. Coffee, Bakery, Burgers",itemDescriptionLabel:"Description (optional)",itemDescriptio